use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::process::{Command, Output};
use std::thread;
use std::time::{Duration, Instant};

use velnor_actions_contract::config::ValidatedImageReference;
use velnor_actions_contract::workflow::cache_family::CacheFamily;

use super::{CACHE_PRUNE_PATH, prune_script, prune_targets, render_cache_prune_yml};

const MARKER: &str =
    "# Generated by Velnor Actions 0.1.38; edit .velnor/config.toml and regenerate.\n";
const SCALE_TOKEN: &str = "scale-set:velnor+ubuntu-26.04-scale-set";
const IMAGE: &str = "ghcr.io/tailrocks/velnor-job@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
const REF: &str = "refs/heads/main";
const LIST_PATH: &str =
    "GET /repos/tailrocks/velnor-new/actions/caches?ref=refs%2Fheads%2Fmain&per_page=100&page=1";

fn mock_response(stream: &mut TcpStream, status: &str, body: &str) {
    write!(
        stream,
        "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    )
    .expect("The mock API writes its response.");
}

fn request(stream: &mut TcpStream) -> String {
    let mut bytes = Vec::new();
    let mut byte = [0_u8; 1];
    while !bytes.ends_with(b"\r\n\r\n") {
        stream
            .read_exact(&mut byte)
            .expect("The mock API reads request headers.");
        bytes.push(byte[0]);
    }
    String::from_utf8(bytes).expect("Request headers are UTF-8.")
}

fn run_client(script: &str, address: &str) -> Output {
    Command::new("python3")
        .arg("-c")
        .arg(script)
        .env("GH_REPO", "tailrocks/velnor-new")
        .env("GH_API_URL", address)
        .env("GH_TOKEN", "test-token")
        .env("GITHUB_REF", REF)
        .env("EXPECTED_REF", REF)
        .output()
        .expect("The prune client runs.")
}

#[test]
fn the_workflow_is_marked_push_only_and_gives_write_scope_to_one_job() {
    let file = render_cache_prune_yml("ubuntu-26.04", None, "main", "0.1.38")
        .expect("The workflow renders.");
    assert_eq!(file.path, CACHE_PRUNE_PATH);
    assert!(file.bytes.starts_with(MARKER));
    assert!(
        file.bytes
            .contains("\"on\":\n  push:\n    branches:\n      - main\n")
    );
    assert!(!file.bytes.contains("  pull_request:"));
    assert!(file.bytes.contains("if: github.ref_protected == true\n"));
    assert!(file.bytes.contains("permissions: {}\n"));
    assert_eq!(file.bytes.matches("actions: write").count(), 1);
    assert!(!file.bytes.contains("actions/checkout"));
    assert!(file.bytes.contains("runs-on: ubuntu-26.04\n"));
    assert!(file.bytes.contains("GH_API_URL: ${{ github.api_url }}"));
    assert!(!file.bytes.contains("gh cache"));
}

#[test]
fn a_scale_set_route_requires_and_uses_its_immutable_container() {
    let image = ValidatedImageReference::parse(IMAGE).expect("The test image is immutable.");
    let file = render_cache_prune_yml(SCALE_TOKEN, Some(&image), "main", "0.1.38")
        .expect("The Scale Set workflow renders.");
    assert!(
        file.bytes
            .contains("runs-on: [velnor, ubuntu-26.04-scale-set]\n")
    );
    assert!(
        file.bytes
            .contains(&format!("container:\n      image: {IMAGE}\n"))
    );
    assert!(!file.bytes.contains("ubuntu-latest"));
    assert!(render_cache_prune_yml(SCALE_TOKEN, None, "main", "0.1.38").is_err());
    assert!(render_cache_prune_yml("ubuntu-26.04", Some(&image), "main", "0.1.38").is_err());
}

#[test]
fn each_family_uses_its_trusted_prefix_and_retention_count() {
    let targets = prune_targets();
    assert_eq!(targets.len(), CacheFamily::ALL.len());
    let script = prune_script();
    for (prefix, retained) in targets {
        assert!(script.contains(&prefix));
        assert!(script.contains(&format!("\"retained\":{retained}")));
    }
    assert!(script.contains("refs/heads/"));
    assert!(!script.contains("gh cache"));
    assert!(!script.contains("delete --all"));
}

#[test]
fn the_client_retains_newest_per_unit_and_deletes_only_superseded_trusted_keys() {
    let (body, expected_deleted) = retention_test_page();
    let delete_count = expected_deleted.len();
    let listener = TcpListener::bind("127.0.0.1:0").expect("The mock API binds.");
    let address = listener
        .local_addr()
        .expect("The mock API address is available.");
    let server = thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("The mock API accepts listing.");
        let headers = request(&mut stream);
        let line = headers.lines().next().expect("The request line exists.");
        assert!(line.starts_with(LIST_PATH));
        assert!(headers.contains("Authorization: Bearer test-token\r\n"));
        mock_response(&mut stream, "200 OK", &body);

        let mut deleted = Vec::new();
        for _ in 0..delete_count {
            let (mut stream, _) = listener.accept().expect("The mock API accepts deletion.");
            let headers = request(&mut stream);
            let line = headers
                .lines()
                .next()
                .expect("The delete request line exists.");
            let path = line
                .split_whitespace()
                .nth(1)
                .expect("The request path exists.");
            assert!(path.starts_with("/repos/tailrocks/velnor-new/actions/caches/"));
            assert!(headers.contains("Authorization: Bearer test-token\r\n"));
            deleted.push(
                path.rsplit('/')
                    .next()
                    .expect("The cache ID must exist.")
                    .parse::<usize>()
                    .expect("The cache ID must be numeric."),
            );
            mock_response(&mut stream, "204 No Content", "");
        }
        deleted
    });
    let output = run_client(&prune_script(), &format!("http://{address}"));
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        server.join().expect("The API server finishes."),
        expected_deleted
    );
}

fn retention_test_page() -> (String, Vec<usize>) {
    let (prefix, retained) = prune_targets()[0].clone();
    let unit = format!("{prefix}unit-a");
    let other = format!("{}unit-b", prune_targets()[1].0);
    let count = usize::try_from(retained + 2).expect("The retained count fits usize.");
    let mut rows = Vec::new();
    let mut expected_deleted = Vec::new();
    for index in (0..count).rev() {
        let id = 100 + index;
        let key = format!("{unit}-s256-{:064x}", index + 1);
        let created_at = format!("2026-10-21T00:{index:02}:00Z");
        rows.push(format!(
            r#"{{"id":{id},"ref":"{REF}","key":"{key}","created_at":"{created_at}"}}"#
        ));
        if index < 2 {
            expected_deleted.push(id);
        }
    }
    rows.push(format!(
        r#"{{"id":999,"ref":"{REF}","key":"{other}-s256-{}","created_at":"2026-10-21T00:00:00Z"}}"#,
        "ab".repeat(32)
    ));
    let pr_key = format!(
        "{}pr-unit-c-s256-{}",
        CacheFamily::ALL[0].key_prefix(),
        "cd".repeat(32)
    );
    rows.push(format!(
        r#"{{"id":998,"ref":"{REF}","key":"{pr_key}","created_at":"2026-10-21T00:00:00Z"}}"#
    ));
    rows.push(format!(
        r#"{{"id":997,"ref":"{REF}","key":"other-family-unit-s256-{}","created_at":"2026-10-21T00:00:00Z"}}"#,
        "ef".repeat(32)
    ));
    let body = format!(
        r#"{{"total_count":{},"actions_caches":[{}]}}"#,
        rows.len(),
        rows.join(",")
    );
    expected_deleted.sort_unstable();
    (body, expected_deleted)
}

#[test]
fn malformed_trusted_keys_and_incomplete_later_pages_fail_before_deletion() {
    let trusted = prune_targets()[0].0.clone();
    let malformed = format!(
        r#"{{"total_count":1,"actions_caches":[{{"id":1,"ref":"{REF}","key":"{trusted}missing-digest","created_at":"2026-10-21T00:00:00Z"}}]}}"#
    );
    let output = run_single_list_response(&malformed);
    assert!(!output.status.success());
    assert!(String::from_utf8_lossy(&output.stderr).contains("invalid_trusted_cache_key"));

    let rows = (0..100)
        .map(|index| {
            format!(
                r#"{{"id":{},"ref":"{REF}","key":"{}unit-{index}-s256-{}","created_at":"2026-10-21T00:00:00Z"}}"#,
                index + 1,
                trusted,
                "ab".repeat(32)
            )
        })
        .collect::<Vec<_>>();
    let first = format!(
        r#"{{"total_count":101,"actions_caches":[{}]}}"#,
        rows.join(",")
    );
    let second = format!(
        r#"{{"total_count":101,"actions_caches":[{{"id":101,"ref":"refs/heads/other","key":"{trusted}later-s256-{}","created_at":"2026-10-21T00:00:00Z"}}]}}"#,
        "bc".repeat(32)
    );
    let (listener, address) = local_listener();
    let server = thread::spawn(move || {
        for (page, body) in [(1, first), (2, second)] {
            let (mut stream, _) = listener.accept().expect("The API accepts each page.");
            let headers = request(&mut stream);
            assert!(
                headers
                    .lines()
                    .next()
                    .unwrap_or_default()
                    .contains(&format!("page={page}"))
            );
            mock_response(&mut stream, "200 OK", &body);
        }
        listener
            .set_nonblocking(true)
            .expect("The mock API enables nonblocking inspection.");
        let until = Instant::now() + Duration::from_millis(100);
        while Instant::now() < until {
            match listener.accept() {
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    thread::sleep(Duration::from_millis(2));
                }
                Ok(_) | Err(_) => return false,
            }
        }
        true
    });
    let output = run_client(&prune_script(), &format!("http://{address}"));
    assert!(output.status.success());
    assert!(String::from_utf8_lossy(&output.stdout).contains("cache_unavailable"));
    assert!(server.join().expect("The mock API finishes."));
}

fn local_listener() -> (TcpListener, std::net::SocketAddr) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("The mock API binds.");
    let address = listener
        .local_addr()
        .expect("The mock API address is available.");
    (listener, address)
}

fn run_single_list_response(body: &str) -> Output {
    let (listener, address) = local_listener();
    let body = body.to_owned();
    let server = thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("The API accepts listing.");
        let headers = request(&mut stream);
        assert!(
            headers
                .lines()
                .next()
                .unwrap_or_default()
                .starts_with(LIST_PATH)
        );
        mock_response(&mut stream, "200 OK", &body);
    });
    let output = run_client(&prune_script(), &format!("http://{address}"));
    server
        .join()
        .expect("The mock API finishes without a DELETE.");
    output
}

#[test]
fn an_unavailable_cache_list_warns_without_deleting_entries() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("The mock API binds.");
    let address = listener
        .local_addr()
        .expect("The mock API address is available.");
    let server = thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("The mock API accepts listing.");
        let headers = request(&mut stream);
        assert!(
            headers
                .lines()
                .next()
                .unwrap_or_default()
                .starts_with(LIST_PATH)
        );
        mock_response(&mut stream, "403 Forbidden", "{}");
    });
    let output = run_client(&prune_script(), &format!("http://{address}"));
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(String::from_utf8_lossy(&output.stdout).contains("cache_unavailable"));
    server.join().expect("The API server finishes.");
}
